  class RecordingWS:
   MAX_FRAMES=int(os.environ.get('CL_RECORD_MAX_FRAMES','600'))
   def __init__(self,ws):self.ws=ws;self.frames=[];(out/'frames').mkdir(exist_ok=True)
   def call(self,method,**params):
    if method == 'Page.navigate' or method.startswith('Input.dispatch'):self.call('Page.bringToFront')
    ws=self.ws;ws.id+=1;my=ws.id;ws.send({'id':my,'method':method,'params':params})
    while True:
     m=ws.recv()
     if m.get('method')=='Page.screencastFrame':
      p=m['params'];name=None
      if len(self.frames)<RecordingWS.MAX_FRAMES:
       name='frames/%06d.jpg'%len(self.frames);(out/name).write_bytes(base64.b64decode(p['data']))
      self.frames.append({'path':name,'timestamp':p['metadata']['timestamp']})
      ws.id+=1;ws.send({'id':ws.id,'method':'Page.screencastFrameAck','params':{'sessionId':p['sessionId']}})
      if len(self.frames)==RecordingWS.MAX_FRAMES:
       ws.id+=1;ws.send({'id':ws.id,'method':'Page.stopScreencast','params':{}})
     if m.get('id')==my:
      if 'error'in m:raise RuntimeError(m['error'])
      return m.get('result',{})
