def native_chapter_lens_main():
 import os
 if os.environ.get('CL_GPU')!='1':raise SystemExit('CL_GPU=1 required; serial GPU slot')
 a=argparse.ArgumentParser();a.add_argument('--chapter-lens',action='store_true');a.add_argument('--base',default='http://127.0.0.1:8002/');a.add_argument('--width',type=int,default=1440);a.add_argument('--reduced',action='store_true');a.add_argument('--motion',action='store_true');args=a.parse_args()
 out=Path(os.environ['CL_SHOTS'])/('m90-native-'+str(args.width)+'-'+str(args.reduced)+('-motion' if args.motion else ''));out.mkdir(parents=True,exist_ok=True)
 r=Wave2AuditRunner(width=args.width,height=844 if args.width<600 else 900,dpr=1);checks=[]
 def ev(code):
  v=r.eval(code)
  if isinstance(v,dict) and v.get('__evalError'):raise RuntimeError(v)
  return v
 def wait(code,timeout=30):
  end=time.monotonic()+timeout
  while time.monotonic()<end:
   if ev(code):return True
   time.sleep(.08)
  raise RuntimeError('M90 wait timeout: '+code)
 def check(name,code):
  v=ev(code);checks.append({'name':name,'ok':v is True,'actual':v});print(('PASS ' if v is True else 'FAIL ')+name,flush=True)
 def tap(sel,settle=.2):
  ev('document.querySelector('+json.dumps(sel)+').scrollIntoView({block:"center",inline:"center"})');time.sleep(.12)
  p=ev('(()=>{let e=document.querySelector('+json.dumps(sel)+'),b=e.getBoundingClientRect(),h=document.elementFromPoint(b.x+b.width/2,b.y+b.height/2);return {x:b.x+b.width/2,y:b.y+b.height/2,hit:h===e||e.contains(h)}})()')
  if not p['hit']:raise RuntimeError('M90 control obscured: '+sel)
  for typ in ['mouseMoved','mousePressed','mouseReleased']:r.ws.call('Input.dispatchMouseEvent',type=typ,x=p['x'],y=p['y'],button='left',clickCount=1)
  time.sleep(settle)
